import { cookies } from 'next/headers';
import { SSOUserInfo, SSOTokenResponse } from '../types';

export const SSO_COOKIE_NAME = 'sso_session';
export const SSO_ACCESS_TOKEN_COOKIE = 'sso_access_token';

export interface SSOSessionData {
  user: SSOUserInfo;
  tokens: SSOTokenResponse;
}

/**
 * Get the current SSO Session from cookies (for Server Components & Route Handlers in Next.js App Router)
 */
export async function getSSOSession(): Promise<SSOSessionData | null> {
  try {
    const cookieStore = await cookies();
    const sessionCookie = cookieStore.get(SSO_COOKIE_NAME);
    if (!sessionCookie || !sessionCookie.value) {
      return null;
    }

    const decoded = Buffer.from(sessionCookie.value, 'base64').toString('utf-8');
    return JSON.parse(decoded) as SSOSessionData;
  } catch (error) {
    return null;
  }
}

/**
 * Get only the SSO access token from cookies
 */
export async function getSSOAccessToken(): Promise<string | null> {
  const session = await getSSOSession();
  return session?.tokens?.access_token || null;
}
