import { NextRequest, NextResponse } from 'next/server';
import { SSOClient } from '../client';
import { SSOConfig, SSOUserInfo, SSOTokenResponse } from '../types';
import { SSO_COOKIE_NAME, SSO_ACCESS_TOKEN_COOKIE } from './cookies';

export interface SSORouteHandlerOptions {
  /** SSO configuration overrides */
  config?: Partial<SSOConfig>;
  /** Default redirect path after successful login (default: "/dashboard") */
  redirectTo?: string;
  /** Role-based redirect map (e.g. { admin: "/admin", dosen: "/dosen" }) */
  roleRedirects?: Record<string, string>;
  /** Callback hook called after user is authenticated */
  onAuthenticated?: (user: SSOUserInfo, tokens: SSOTokenResponse) => Promise<void> | void;
}

/**
 * Handle SSO Login Redirect (/api/sso/redirect)
 */
export async function handleSSORedirect(
  request: NextRequest,
  options?: SSORouteHandlerOptions
): Promise<NextResponse> {
  const ssoClient = new SSOClient(options?.config);
  
  // Calculate callback URL dynamically if not set
  const requestUrl = new URL(request.url);
  const redirectUri =
    ssoClient.config.redirectUri ||
    `${requestUrl.protocol}//${requestUrl.host}/api/sso/callback`;

  const authUrl = ssoClient.getAuthorizationUrl({
    redirectUri,
    prompt: ssoClient.config.prompt,
  });

  return NextResponse.redirect(authUrl);
}

/**
 * Handle SSO Callback (/api/sso/callback)
 */
export async function handleSSOCallback(
  request: NextRequest,
  options?: SSORouteHandlerOptions
): Promise<NextResponse> {
  const ssoClient = new SSOClient(options?.config);
  const searchParams = request.nextUrl.searchParams;
  const code = searchParams.get('code');
  const error = searchParams.get('error');

  if (error) {
    return NextResponse.json(
      { error: `SSO authorization denied: ${error}` },
      { status: 400 }
    );
  }

  if (!code) {
    return NextResponse.json(
      { error: 'Missing authorization code in query parameters' },
      { status: 400 }
    );
  }

  try {
    const requestUrl = new URL(request.url);
    const redirectUri =
      ssoClient.config.redirectUri ||
      `${requestUrl.protocol}//${requestUrl.host}/api/sso/callback`;

    // 1. Exchange code for tokens
    const tokens = await ssoClient.exchangeCode(code, redirectUri);

    // 2. Fetch UserInfo
    const userInfo = await ssoClient.getUserInfo(tokens.access_token);

    // 3. Trigger custom callback hook if provided
    if (options?.onAuthenticated) {
      await options.onAuthenticated(userInfo, tokens);
    }

    // 4. Resolve target redirect path (role-based or default)
    let targetPath = options?.redirectTo || '/dashboard';
    if (options?.roleRedirects && userInfo.role && options.roleRedirects[userInfo.role]) {
      targetPath = options.roleRedirects[userInfo.role];
    }

    const redirectUrl = new URL(targetPath, request.url);
    const response = NextResponse.redirect(redirectUrl);

    // 5. Store session in HTTP-Only Cookie
    const sessionData = {
      user: userInfo,
      tokens: tokens,
    };
    const encodedSession = Buffer.from(JSON.stringify(sessionData)).toString('base64');

    response.cookies.set(SSO_COOKIE_NAME, encodedSession, {
      httpOnly: true,
      secure: process.env.NODE_NODE_ENV === 'production',
      sameSite: 'lax',
      path: '/',
      maxAge: tokens.expires_in || 86400, // Default 24h
    });

    response.cookies.set(SSO_ACCESS_TOKEN_COOKIE, tokens.access_token, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'lax',
      path: '/',
      maxAge: tokens.expires_in || 86400,
    });

    return response;
  } catch (err: any) {
    return NextResponse.json(
      { error: err.message || 'SSO Authentication failed' },
      { status: 500 }
    );
  }
}

/**
 * Handle SSO Logout (/api/sso/logout)
 */
export async function handleSSOLogout(
  request: NextRequest,
  options?: { redirectTo?: string }
): Promise<NextResponse> {
  const targetUrl = new URL(options?.redirectTo || '/', request.url);
  const response = NextResponse.redirect(targetUrl);

  // Clear session cookies locally
  response.cookies.set(SSO_COOKIE_NAME, '', {
    httpOnly: true,
    path: '/',
    maxAge: 0,
  });

  response.cookies.set(SSO_ACCESS_TOKEN_COOKIE, '', {
    httpOnly: true,
    path: '/',
    maxAge: 0,
  });

  return response;
}

/**
 * Create a catch-all Route Handler for Next.js App Router
 * Usage in `app/api/sso/[...sso]/route.ts`:
 * ```ts
 * import { createSSORouteHandlers } from '@webkampus/sso-client-next/next';
 * export const { GET, POST } = createSSORouteHandlers();
 * ```
 */
export function createSSORouteHandlers(options?: SSORouteHandlerOptions) {
  const handler = async (request: NextRequest) => {
    const url = new URL(request.url);
    const path = url.pathname;

    if (path.endsWith('/redirect')) {
      return handleSSORedirect(request, options);
    }

    if (path.endsWith('/callback')) {
      return handleSSOCallback(request, options);
    }

    if (path.endsWith('/logout')) {
      return handleSSOLogout(request, { redirectTo: options?.redirectTo });
    }

    return NextResponse.json({ error: 'Endpoint not found' }, { status: 404 });
  };

  return {
    GET: handler,
    POST: handler,
  };
}
