import { SSOConfig } from './types';

/**
 * Load SSOConfig from process.env or provided override parameters.
 */
export function getSSOConfig(overrideConfig?: Partial<SSOConfig>): SSOConfig {
  const ssoUrl = (
    overrideConfig?.ssoUrl ||
    process.env.SSO_URL ||
    process.env.NEXT_PUBLIC_SSO_URL ||
    'http://localhost:8000'
  ).replace(/\/+$/, ''); // Strip trailing slashes

  const clientId =
    overrideConfig?.clientId ||
    process.env.SSO_CLIENT_ID ||
    process.env.NEXT_PUBLIC_SSO_CLIENT_ID ||
    '';

  const clientSecret =
    overrideConfig?.clientSecret ||
    process.env.SSO_CLIENT_SECRET ||
    '';

  const redirectUri =
    overrideConfig?.redirectUri ||
    process.env.SSO_REDIRECT_URI ||
    '';

  const scope =
    overrideConfig?.scope ||
    process.env.SSO_SCOPE ||
    '*';

  const prompt =
    overrideConfig?.prompt !== undefined
      ? overrideConfig.prompt
      : (process.env.SSO_PROMPT ?? 'login');

  return {
    ssoUrl,
    clientId,
    clientSecret,
    redirectUri,
    scope,
    prompt: prompt || null,
  };
}
